const eventos = $input.all();
const dataStr = $('When Executed by Another Workflow').first().json.data_consulta || '';

// Calcula o dia da semana exato da data consultada para evitar erro de Terça vs Quinta
const diasSemana = ['Domingo', 'Segunda-feira', 'Terça-feira', 'Quarta-feira', 'Quinta-feira', 'Sexta-feira', 'Sábado'];
let diaSemanaTexto = '';
if (dataStr) {
  const [ano, mes, dia] = dataStr.split('-').map(Number);
  const dataObj = new Date(Date.UTC(ano, mes - 1, dia, 12, 0, 0));
  diaSemanaTexto = ` (${diasSemana[dataObj.getUTCDay()]})`;
}

// Se o nó do Google Calendar não retornar eventos (dia 100% livre à tarde)
if (!eventos.length || !eventos[0].json || (!eventos[0].json.start && !eventos[0].json.id)) {
  return [{
    json: {
      disponibilidade: `Agenda 100% livre na tarde de ${dataStr}${diaSemanaTexto}. Horários disponíveis para oferecer: entre 13:30 e 17:30.`
    }
  }];
}

// Se houver eventos, lista os intervalos ocupados
const ocupados = eventos
  .filter(e => e.json && e.json.start)
  .map(e => {
    if (e.json.start.dateTime) {
      const inicio = new Date(e.json.start.dateTime).toLocaleTimeString('pt-BR', {
        hour: '2-digit',
        minute: '2-digit',
        timeZone: 'America/Sao_Paulo'
      });
      const fim = new Date(e.json.end.dateTime).toLocaleTimeString('pt-BR', {
        hour: '2-digit',
        minute: '2-digit',
        timeZone: 'America/Sao_Paulo'
      });
      return `${inicio} às ${fim}`;
    }
    return 'Dia inteiro ocupado';
  });

return [{
  json: {
    disponibilidade: `Na data ${dataStr}${diaSemanaTexto}, os seguintes horários JÁ ESTÃO OCUPADOS: ${ocupados.join(' | ')}. Ofereça apenas horários à tarde (entre 13:30 e 17:30) que estejam FORA desses intervalos.`
  }
}];
